  @Test
  fun sCSpecEntryXdrRejectsAnArmItDoesNotDeclare() {
    assertFailsWith<IllegalArgumentException> {
      SCSpecEntryXdr.fromXdrJsonElement(buildJsonObject { put("not_a_name_this_type_declares", JsonNull) })
    }
    assertFailsWith<IllegalArgumentException> {
      SCSpecEntryXdr.fromXdrJsonElement(
        buildJsonObject {
          put("not_a_name_this_type_declares", JsonNull)
          put("not_a_name_this_type_declares_too", JsonNull)
        }
      )
    }
    assertFailsWith<IllegalArgumentException> { SCSpecEntryXdr.fromXdrJsonElement(JsonNull) }
  }

